<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';

interface Props { userName?: string; userEmail?: string; canUpdate?: boolean }
interface Shipment { id: number; provider: string; tracking_code?: string | null; provider_shipment_id?: string | null; status: string; recipient_name: string; recipient_phone: string; recipient_address: string; cod_amount: string; booked_at?: string | null; delivered_at?: string | null; order?: { id: number; order_number: string; customer_name: string; customer_phone: string; grand_total: string; status: string }; creator?: { name: string } }
interface Location { id: number; name: string; code?: string | null; access_level: string }
interface Event { id: number; previous_status?: string; received_status: string; outcome: string; payload?: Record<string, unknown>; received_at: string; provider: string }
const props = withDefaults(defineProps<Props>(), { userName: '', userEmail: '', canUpdate: false });
const shipments = ref<Shipment[]>([]); const locations = ref<Location[]>([]); const summary = ref<Record<string, number>>({});
const loading = ref(false); const error = ref(''); const success = ref(''); const page = ref(1); const lastPage = ref(1);
const filters = reactive({ q: '', status: '', provider: '', location_id: '' });
const statusModal = ref(false); const selected = ref<Shipment | null>(null); const events = ref<Event[]>([]); const eventModal = ref(false); const saving = ref(false);
const statusForm = reactive({ status: '', reason: '' });
const statuses = ['queued','booking','booked','in_transit','partially_delivered','delivered','delivery_failed','returned','cancelled','failed'];
const statusLabel = (s: string) => s.replaceAll('_',' ').replace(/\b\w/g, c => c.toUpperCase());
const money = (v?: string | number) => new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT',maximumFractionDigits:2}).format(Number(v ?? 0));
const csrf = () => decodeURIComponent(document.cookie.split('; ').find(v => v.startsWith('XSRF-TOKEN='))?.split('=').slice(1).join('=') ?? '');
async function api<T>(url: string, options: RequestInit = {}): Promise<T> {
 const response = await fetch(url,{credentials:'same-origin',...options,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest',...(options.body?{'Content-Type':'application/json','X-XSRF-TOKEN':csrf()}:{}),...(options.headers??{})}});
 const body = await response.json().catch(()=>({})); if(!response.ok) throw new Error(body.message || Object.values(body.errors??{}).flat().join(' ') || `Request failed (${response.status})`); return body as T;
}
const query = computed(() => { const p = new URLSearchParams({page:String(page.value),per_page:'25'}); Object.entries(filters).forEach(([k,v])=>{if(v)p.set(k,v)}); return p.toString(); });
async function load() { loading.value=true; error.value=''; try { const r=await api<{data:{data:Shipment[];current_page:number;last_page:number};summary:Record<string,number>;locations:Location[]}>(`/api/shipping/overview?${query.value}`); shipments.value=r.data.data; page.value=r.data.current_page; lastPage.value=r.data.last_page; summary.value=r.summary; locations.value=r.locations; } catch(e){error.value=e instanceof Error?e.message:'Unable to load delivery records.'} finally{loading.value=false} }
let searchTimer: ReturnType<typeof setTimeout> | undefined;
watch(()=>({...filters}),()=>{page.value=1; if(searchTimer)clearTimeout(searchTimer); searchTimer=setTimeout(load,250)});
function openStatus(s:Shipment){selected.value=s;statusForm.status=s.status;statusForm.reason='';statusModal.value=true}
async function saveStatus(){if(!selected.value)return;saving.value=true;error.value='';success.value='';try{await api(`/api/shipping/shipments/${selected.value.id}/status`,{method:'PATCH',body:JSON.stringify(statusForm)});statusModal.value=false;success.value='Delivery status updated and added to shipment history.';await load()}catch(e){error.value=e instanceof Error?e.message:'Unable to update delivery status.'}finally{saving.value=false}}
async function showEvents(s:Shipment){selected.value=s;try{const r=await api<{data:Event[]}>(`/api/shipping/shipments/${s.id}/events`);events.value=r.data;eventModal.value=true}catch(e){error.value=e instanceof Error?e.message:'Unable to load shipment history.'}}
onMounted(load);
</script>

<template>
 <Head title="Shipping & Delivery" />
 <ErpLayout :user-name="props.userName" :user-email="props.userEmail">
  <div class="space-y-6 p-5 lg:p-7">
   <div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-[.16em] text-slate-500">Logistics operations</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Shipping & Delivery</h1><p class="mt-1 text-sm text-slate-500">Monitor courier shipments, delivery progress, exceptions and proof of status changes.</p></div><button class="rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50" @click="load">Refresh</button></div>
   <div v-if="error" class="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{ error }}</div><div v-if="success" class="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">{{ success }}</div>
   <div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
    <div v-for="card in [{label:'Total shipments',key:'total'},{label:'Pending / booked',key:'pending'},{label:'In transit',key:'in_transit'},{label:'Delivered',key:'delivered'},{label:'Delivery exceptions',key:'exceptions'}]" :key="card.key" class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><p class="text-sm text-slate-500">{{ card.label }}</p><p class="mt-2 text-2xl font-bold text-slate-900">{{ summary[card.key] ?? 0 }}</p></div>
   </div>
   <section class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
    <input v-model="filters.q" class="rounded-xl border-slate-300 text-sm" placeholder="Search order, tracking, customer…" />
    <select v-model="filters.status" class="rounded-xl border-slate-300 text-sm"><option value="">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{ statusLabel(s) }}</option></select>
    <select v-model="filters.provider" class="rounded-xl border-slate-300 text-sm"><option value="">All couriers</option><option v-for="p in ['steadfast','redx','pathao','carrybee','custom']" :key="p" :value="p">{{ p.toUpperCase() }}</option></select>
    <select v-model="filters.location_id" class="rounded-xl border-slate-300 text-sm"><option value="">All accessible locations</option><option v-for="l in locations" :key="l.id" :value="String(l.id)">{{ l.name }}</option></select>
   </div></section>
   <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h2 class="font-semibold text-slate-900">Shipment register</h2><p class="text-xs text-slate-500">{{ shipments.length }} records on this page</p></div><span v-if="loading" class="text-xs text-slate-500">Loading…</span></div>
    <div class="overflow-x-auto"><table class="min-w-[1050px] w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Order / Customer</th><th class="px-4 py-3">Courier / Tracking</th><th class="px-4 py-3">Recipient</th><th class="px-4 py-3">COD</th><th class="px-4 py-3">Status</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="s in shipments" :key="s.id" class="hover:bg-slate-50/70"><td class="px-5 py-4"><p class="font-semibold text-slate-900">{{ s.order?.order_number ?? '—' }}</p><p class="text-xs text-slate-500">{{ s.order?.customer_name ?? 'Customer' }}</p></td><td class="px-4 py-4"><p class="font-medium text-slate-800">{{ s.provider.toUpperCase() }}</p><p class="text-xs text-slate-500">{{ s.tracking_code || s.provider_shipment_id || 'Tracking pending' }}</p></td><td class="px-4 py-4"><p>{{ s.recipient_name }}</p><p class="text-xs text-slate-500">{{ s.recipient_phone }}</p></td><td class="px-4 py-4 font-medium">{{ money(s.cod_amount) }}</td><td class="px-4 py-4"><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-700">{{ statusLabel(s.status) }}</span></td><td class="px-4 py-4 text-right"><div class="flex justify-end gap-2"><button class="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-semibold hover:bg-slate-50" @click="showEvents(s)">History</button><button v-if="props.canUpdate" class="rounded-lg bg-blue-700 px-3 py-1.5 text-xs font-semibold text-white hover:bg-blue-800" @click="openStatus(s)">Update</button></div></td></tr><tr v-if="!loading && !shipments.length"><td colspan="6" class="px-5 py-14 text-center text-slate-500">No shipments match the selected filters.</td></tr></tbody></table></div>
    <div class="flex items-center justify-between border-t border-slate-100 px-5 py-3 text-sm"><span class="text-slate-500">Page {{ page }} of {{ lastPage }}</span><div class="flex gap-2"><button :disabled="page<=1" class="rounded-lg border px-3 py-1.5 disabled:opacity-40" @click="page--;load()">Previous</button><button :disabled="page>=lastPage" class="rounded-lg border px-3 py-1.5 disabled:opacity-40" @click="page++;load()">Next</button></div></div>
   </section>
   <p class="text-xs leading-5 text-slate-500">Courier COD amounts are operational collection amounts, not recognized revenue. Reconcile courier remittances against bank/cash receipts before posting finance entries.</p>
  </div>
  <div v-if="statusModal && selected" class="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Update delivery status</h2><p class="mt-1 text-sm text-slate-500">{{ selected.order?.order_number }} · {{ selected.provider.toUpperCase() }}</p><form class="mt-5 space-y-4" @submit.prevent="saveStatus"><label class="block text-sm font-medium">New status<select v-model="statusForm.status" required class="mt-1.5 w-full rounded-xl border-slate-300"><option v-for="s in statuses" :key="s" :value="s">{{ statusLabel(s) }}</option></select></label><label class="block text-sm font-medium">Reason / operational note<textarea v-model="statusForm.reason" required minlength="5" maxlength="1000" rows="3" class="mt-1.5 w-full rounded-xl border-slate-300" placeholder="Record why this status is being changed…" /></label><div class="flex justify-end gap-2"><button type="button" class="rounded-xl border px-4 py-2" @click="statusModal=false">Cancel</button><button :disabled="saving" class="rounded-xl bg-blue-700 px-4 py-2 font-semibold text-white disabled:opacity-50">{{ saving?'Saving…':'Save status' }}</button></div></form></div></div>
  <div v-if="eventModal && selected" class="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/50 p-4"><div class="max-h-[80vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div class="flex justify-between"><div><h2 class="text-lg font-bold">Shipment history</h2><p class="text-sm text-slate-500">{{ selected.order?.order_number }} · {{ selected.tracking_code || selected.provider }}</p></div><button class="text-slate-500" @click="eventModal=false">✕</button></div><div v-if="!events.length" class="py-10 text-center text-slate-500">No status events recorded.</div><ol v-else class="mt-5 space-y-4"><li v-for="ev in events" :key="ev.id" class="border-l-2 border-blue-200 pl-4"><p class="font-semibold">{{ statusLabel(ev.previous_status || 'created') }} → {{ statusLabel(ev.received_status) }}</p><p class="text-xs text-slate-500">{{ new Date(ev.received_at).toLocaleString() }} · {{ ev.provider }} · {{ ev.outcome }}</p><p v-if="ev.payload?.reason" class="mt-1 text-sm text-slate-700">{{ ev.payload.reason }}</p></li></ol></div></div>
 </ErpLayout>
</template>
